import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { roundCents } from './money.js';

/**
 * Invoices overdue as of a date, sorted by days overdue (most first).
 * @param {Array<object>} invoices
 * @param {string} asOf (YYYY-MM-DD format)
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  const overdue = (invoices || [])
    .filter((inv) => ['issued', 'partially_paid'].includes(inv.status))
    .filter((inv) => inv.dueDate < asOf)
    .map((inv) => {
      const due = balanceDue(inv);
      const daysOverdue = daysBetween(inv.dueDate, asOf);
      return {
        number: inv.number,
        customerId: inv.customerId,
        dueDate: inv.dueDate,
        daysOverdue,
        due,
      };
    })
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return overdue;
}

/**
 * VAT summary across invoices, grouped by rate.
 * @param {Array<object>} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  const vatMap = {};

  for (const invoice of (invoices || [])) {
    if (!['issued', 'partially_paid', 'paid'].includes(invoice.status)) continue;
    if (!invoice.lines) continue;

    for (const line of invoice.lines) {
      const lineTotal = line.qty * line.unitPrice;
      let lineDiscount = 0;
      if (line.discountPercent !== undefined && line.discountPercent !== null) {
        lineDiscount = Math.max(0, (line.discountPercent / 100) * lineTotal);
      }
      const discountedAmount = Math.max(0, lineTotal - lineDiscount);
      const rate = line.vatRate || 0;
      const lineVat = rate > 0 ? roundCents(discountedAmount * (rate / 100)) : 0;

      if (!vatMap[rate]) {
        vatMap[rate] = { rate, base: 0, vat: 0 };
      }
      vatMap[rate].base += discountedAmount;
      vatMap[rate].vat += lineVat;
    }
  }

  const result = Object.values(vatMap)
    .map((item) => ({ ...item, base: roundCents(item.base) }))
    .sort((a, b) => b.rate - a.rate);
  return result;
}

/**
 * Late fee on an invoice: 0.04% per day overdue.
 * @param {object} invoice
 * @param {string} asOf (YYYY-MM-DD format)
 * @returns {number} late fee in cents
 */
export function lateFee(invoice, asOf) {
  if (!invoice || !invoice.dueDate) return 0;

  // Check if overdue
  if (invoice.dueDate >= asOf) return 0;

  // Calculate days overdue
  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  if (daysOverdue <= 0) return 0;

  // Get amount due
  const due = balanceDue(invoice);
  if (due <= 0) return 0;

  // Calculate late fee: 0.04% per day
  const fee = due * 0.0004 * daysOverdue;
  return roundCents(fee);
}

