3	/**
4	 * Exchange rates: units of that currency per euro.
5	 */
6	export const RATES = {
7	  EUR: 1,
8	  USD: 1.085,
9	  GBP: 0.8425,
10	};
11	
12	/**
13	 * Round a (possibly fractional) number of cents to a whole cent, half to even (banker's rounding):
14	 * 124.5 -> 124, 125.5 -> 126, 2.4 -> 2, -0.5 -> 0.
15	 * @param {number} x
16	 * @returns {number}
17	 */
18	export function roundCents(x) {
19	  const r = Math.round(x * 1e6) / 1e6; // drop binary noise such as 124.49999999999999
20	  const floor = Math.floor(r);
21	  const diff = r - floor;
22	  if (diff > 0.5) return floor + 1;
23	  if (diff < 0.5) return floor === 0 ? 0 : floor;
24	  return floor % 2 === 0 ? floor : floor + 1;
25	}
26	
27	/**
28	 * Format cents as euros for people: 123456 -> "€1,234.56", -5 -> "-€0.05".
29	 * @param {number} cents
30	 * @returns {string}
31	 */
32	export function formatEuros(cents) {
33	  const sign = cents < 0 ? '-' : '';
