  const bulkDiscount = roundCents(afterTierDiscount * 0.025);
  const totalDiscount = tierDiscount + bulkDiscount;
  assert.equal(r.value.discount, totalDiscount);
  const discountedAmount = 85000 - totalDiscount;
  const expectedVat = roundCents(discountedAmount * 0.21);
  const expectedTotal = roundCents(85000 - totalDiscount + expectedVat);
  assert.equal(r.value.vat, expectedVat);
